<script setup>
import { createLogger } from '../../utils/logger'
import { onBeforeUnmount, onMounted, ref } from "vue";

const logger = createLogger('GuaxiStatisticsSidebar')

/**
 * 统计页专用 Sidebar：
 * - 只保留图标区（sider-icon-container），不引入主页文件树/分类等内容
 * - 使用 hash 路由进行页面切换
 */
const activePath = ref((window.location.hash || "#/").slice(1) || "/");

const syncActivePath = () => {
  activePath.value = (window.location.hash || "#/").slice(1) || "/";
};

onMounted(() => {
  logger.info("[statistics:sidebar] mounted");
  window.addEventListener("hashchange", syncActivePath);
  syncActivePath();
});

onBeforeUnmount(() => {
  window.removeEventListener("hashchange", syncActivePath);
});

const navigateTo = (path) => {
  logger.info("[statistics:sidebar] navigateTo", path);
  window.location.hash = path;
};
</script>

